package accounting

import (
	"errors"
	"fmt"
	"strings"
	"time"
)

// Side says whether a movement is posted to the debit (debe) or the credit
// (haber) of its account.
type Side string

const (
	Debit  Side = "debit"
	Credit Side = "credit"
)

// Source records how an entry came about (DESIGN.md 8.3, 8.7): typed in by
// hand, or generated by one of the three automatic milestones.
type Source string

const (
	SourceManual     Source = "manual"     // arbitrary movement typed by staff
	SourceCollection Source = "collection" // a billable item was marked Collected
	SourceCommission Source = "commission" // commission accrued to an AE account
	SourceSettlement Source = "settlement" // settlement paid to an AE
	SourceReversal   Source = "reversal"   // contra-entry cancelling another entry
)

// DateLayout is how an entry date is stored and displayed ("2026-10-11").
const DateLayout = "2006-01-02"

// Movement is one line of an entry: an amount posted to the debit or credit
// of one account. Amount is always positive; the Side carries the direction.
type Movement struct {
	AccountCode string `json:"account_code"`
	Side        Side   `json:"side"`
	Amount      Cents  `json:"amount"`
}

// Entry (asiento) groups the movements of one operation. The debit total
// equals the credit total (D-29). Entries are append-only: a mistake is
// corrected with a reversal entry, never by editing or deleting.
type Entry struct {
	ID          int64      `json:"id,omitempty"`  // the entry number shown to people; assigned by the store
	UID         string     `json:"uid,omitempty"` // generated by the module; ties movements to the entry inside one atomic write
	Date        string     `json:"date"`          // DateLayout
	Description string     `json:"description"`
	Source      Source     `json:"source"`
	Reference   string     `json:"reference,omitempty"` // e.g. "item:42", "settlement:7", "entry:12"
	DocID       int64      `json:"doc_id,omitempty"`    // supporting document (receipt, invoice) kept with a manual entry
	Movements   []Movement `json:"movements"`
	CreatedBy   int64      `json:"created_by,omitempty"`
	CreatedAt   string     `json:"created_at,omitempty"`
}

// Totals returns the debit and credit sums of the entry.
func (e Entry) Totals() (debit, credit Cents) {
	for _, m := range e.Movements {
		switch m.Side {
		case Debit:
			debit += m.Amount
		case Credit:
			credit += m.Amount
		}
	}
	return
}

// Errors returned by Validate. Callers can test them with errors.Is.
var (
	ErrUnbalanced     = errors.New("accounting: debit total does not equal credit total")
	ErrTooFewLines    = errors.New("accounting: an entry needs at least one debit and one credit movement")
	ErrBadMovement    = errors.New("accounting: invalid movement")
	ErrUnknownAccount = errors.New("accounting: unknown account")
	ErrNotPostable    = errors.New("accounting: account does not admit movements")
	ErrBadDate        = errors.New("accounting: invalid entry date")
	ErrNoDescription  = errors.New("accounting: description is required")
	ErrPeriodClosed   = errors.New("accounting: the entry date falls in a closed month")
)

// MaxMovementsPerEntry bounds an entry so that it, its movements and the
// state change that triggered it always fit one atomic xolu commit (25 appends).
const MaxMovementsPerEntry = 20

// Validate checks an entry against the chart: a valid date, a description,
// between 2 and MaxMovementsPerEntry movements with positive amounts on known
// postable accounts, at least one on each side, and debit total = credit total.
func (e Entry) Validate(chart *Chart) error {
	if _, err := time.Parse(DateLayout, e.Date); err != nil {
		return fmt.Errorf("%w: %q", ErrBadDate, e.Date)
	}
	if strings.TrimSpace(e.Description) == "" {
		return ErrNoDescription
	}
	if len(e.Movements) < 2 || len(e.Movements) > MaxMovementsPerEntry {
		return fmt.Errorf("%w (got %d movements, want 2..%d)", ErrTooFewLines, len(e.Movements), MaxMovementsPerEntry)
	}
	var hasDebit, hasCredit bool
	for i, m := range e.Movements {
		if m.Amount <= 0 {
			return fmt.Errorf("%w: line %d has a non-positive amount", ErrBadMovement, i+1)
		}
		switch m.Side {
		case Debit:
			hasDebit = true
		case Credit:
			hasCredit = true
		default:
			return fmt.Errorf("%w: line %d has side %q", ErrBadMovement, i+1, m.Side)
		}
		a, ok := chart.Get(m.AccountCode)
		if !ok {
			return fmt.Errorf("%w: %q", ErrUnknownAccount, m.AccountCode)
		}
		if !a.Postable {
			return fmt.Errorf("%w: %s %s", ErrNotPostable, a.Code, a.Name)
		}
	}
	if !hasDebit || !hasCredit {
		return ErrTooFewLines
	}
	d, c := e.Totals()
	if d != c {
		return fmt.Errorf("%w (debit %s, credit %s)", ErrUnbalanced, d, c)
	}
	return nil
}

// Period returns the "YYYY-MM" month the entry date falls in.
func (e Entry) Period() string {
	if len(e.Date) >= 7 {
		return e.Date[:7]
	}
	return ""
}

// Reversal builds the contra-entry of e: same accounts and amounts, opposite
// sides, dated on the given day. It is how a posted entry is corrected.
func (e Entry) Reversal(date string, createdBy int64) Entry {
	r := Entry{
		Date:        date,
		Description: fmt.Sprintf("Reversal of entry #%d: %s", e.ID, e.Description),
		Source:      SourceReversal,
		Reference:   fmt.Sprintf("entry:%d", e.ID),
		CreatedBy:   createdBy,
	}
	for _, m := range e.Movements {
		side := Debit
		if m.Side == Debit {
			side = Credit
		}
		r.Movements = append(r.Movements, Movement{AccountCode: m.AccountCode, Side: side, Amount: m.Amount})
	}
	return r
}
